const $ = (q, root=document) => root.querySelector(q);
const $$ = (q, root=document) => [...root.querySelectorAll(q)];
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key = 'adstudio-project';
const nav = [['overview','总览','⌂'],['canvas','创作画布','◇'],['sources','资料与事实','▤'],['master','三视图母版','◫'],['creative','广告策划','✦'],['prompts','提示词与选图','▧'],['gallery','电商套图','▦'],['video','视频收尾','▶'],['tasks','任务与费用','◷'],['delivery','交付与备份','↥']];
const stages=['三视图','试图','套图','视频镜头','AI辅助'];
let project=null, projects=[], view='overview', rightTab='chat', selectedNode=null, capabilities={}, providerSettings={}, toast='', uploadMode='source', galleryDraft=null, currentPrompt=null, canvasScale=1, canvasPan={x:0,y:0}, canvasDrag=null, createOpen=false, aiPending=null, seeanyPending=null, compareIds=[], uploadParentAsset=null;
const api=async(path,body)=>{const r=await fetch('/api'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const content=await r.json();if(!r.ok)throw Error(content.error||'请求失败');return content};
const act=async(type,body={})=>{if(!project)return;const r=await api(`/projects/${project.id}/action/${type}`,body);project=r.project;render();return r.result};
const notify=(s)=>{toast=s;render();setTimeout(()=>{toast='';const e=$('#toast');if(e)e.remove()},4200)};
const error=(e)=>notify('操作失败：'+(e?.message||e));
const fileUrl=sid=>`/api/projects/${project.id}/file/${sid}`;
const source=id=>project.sources.find(x=>x.id===id);
const asset=id=>project.assets.find(x=>x.id===id);
const assetSrc=a=>a?fileUrl(a.source_id):'';
const approvedBrief=()=>project?.brief_versions.at(-1);
const approvedGallery=()=>project?.gallery.findLast(x=>x.approved);
const fmt=d=>d?new Date(d).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—';
const textField=(name,label,value='',placeholder='')=>`<div class="field"><label>${label}</label><input name="${name}" value="${esc(value)}" placeholder="${esc(placeholder)}"></div>`;
const area=(name,label,value='',placeholder='')=>`<div class="field"><label>${label}</label><textarea name="${name}" placeholder="${esc(placeholder)}">${esc(value)}</textarea></div>`;
const select=(name,label,options,value)=>`<div class="field"><label>${label}</label><select name="${name}">${options.map(o=>`<option value="${esc(o)}" ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;
const formData=e=>Object.fromEntries(new FormData(e).entries());
const empty=(title,desc)=>`<div class="empty"><strong>${title}</strong>${desc||''}</div>`;
const badge=(label,type='')=>`<span class="tag ${type}">${esc(label)}</span>`;
const latest=a=>a?.at(-1);

async function init(){try{projects=await api('/projects');capabilities=await api('/capabilities');providerSettings=await api('/provider-settings');const saved=localStorage.getItem(key);if(saved){try{project=await api('/projects/'+saved)}catch{localStorage.removeItem(key)}}render()}catch(e){document.body.innerHTML=`<div class="landing"><h1>无法连接本地工作台</h1><p>${esc(e.message)}</p></div>`}}
function render(){document.title=project?`${project.name} · 广告电商创作工作台`:'广告电商创作工作台';$('#app').innerHTML=project?workspace():landing();if(aiPending){const box=document.createElement('div');box.innerHTML=aiModal();$('#app').append(box.firstElementChild)}if(seeanyPending){const box=document.createElement('div');box.innerHTML=seeanyModal();$('#app').append(box.firstElementChild)}bind();bindSeeany();}
function landing(){return `<div class="landing"><div class="landing-head"><div class="brand-mark"><span class="brand-logo">✦</span> 广告电商创作工作台</div><span class="tag green">本地单人版</span></div><div class="hero"><div><h2>从产品资料<br>到可交付的创作过程</h2><p>把事实、母版、提示词、分镜、资产和审核决定放在同一条可追溯链路里。</p></div><div style="min-width:220px"><form id="create-form"><div class="field"><label style="color:#b9d8c3">新商品项目</label><input name="name" placeholder="商品或项目名称" required></div><button class="primary" style="width:100%">＋ 创建商品项目</button></form></div></div><div class="section-head"><div><h2>项目</h2><p>所有资料保存在这台电脑上</p></div><div class="row"><input class="search" id="project-search" placeholder="搜索项目、素材或提示词"><button class="ghost" data-click="restore">恢复备份</button></div></div><div id="project-list" class="project-grid">${projectCards(projects)}</div>${toast?`<div class="success" id="toast">${esc(toast)}</div>`:''}</div>${createOpen?`<div class="overlay"><div class="dialog"><div class="row between"><h2>创建商品项目</h2><button class="iconbtn" data-click="close-create">×</button></div><p class="muted">一个商品的资料、视频和套图保存在同一项目中。</p><form id="create-form">${textField('name','商品或项目名称','','例如：迷你空气炸锅')}<button class="primary" style="width:100%">创建并开始收集资料</button></form></div></div>`:''}`}
function projectCards(list){return list.length?list.map(p=>`<div class="project-card" data-open="${p.id}"><div class="row between"><span class="tag ${p.archived?'':'green'}">${p.archived?'已归档':'进行中'}</span><span class="muted tiny">${fmt(p.updated)}</span></div><h3>${esc(p.name)}</h3><p>${p.sources} 份原始资料 · 拼多多试点</p><button class="smallbtn">打开项目 →</button></div>`).join(''):empty('还没有项目','创建一个商品项目开始。')}
function workspace(){return `<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark"><span class="brand-logo">✦</span> 创作工作台</div><small>AD CREATION STUDIO</small></div><button class="project-switch" data-click="home"><span>▧ &nbsp;${esc(project.name)}</span><span>⌄</span></button><div class="side-label">工作流程</div><nav class="nav">${nav.map(([id,name,icon],i)=>`<button data-view="${id}" class="${view===id?'active':''}"><span class="num">${icon}</span>${name}</button>`).join('')}</nav><div class="side-bottom"><button data-click="home">← 所有项目</button><button data-click="archive">${project.archived?'取消归档':'归档项目'}</button></div></aside><main class="main"><header class="topbar"><div><div class="crumb">商品项目 / ${esc(project.name)}</div><h1>${nav.find(n=>n[0]===view)?.[1]}</h1></div><div class="top-actions"><span class="tag ${navigator.onLine?'green':'orange'}">${navigator.onLine?'● 在线':'○ 离线'}</span><button class="ghost" data-click="upload">＋ 导入素材</button></div></header><div class="workspace"><div class="notice">✦ <span>正式生成仅依据已确认版本。连线和编辑不会提交付费任务。</span></div><div class="stagebar">${stagePills()}</div><div class="content">${renderView()}</div></div></main><aside class="right"><div class="right-tabs"><button data-right="chat" class="${rightTab==='chat'?'active':''}">创作对话</button><button data-right="inspector" class="${rightTab==='inspector'?'active':''}">节点检查</button></div><div class="right-body">${rightTab==='chat'?chatView()+chatAiButton():inspectorView()}</div>${rightTab==='chat'?`<form id="chat-form" class="right-footer"><textarea name="text" placeholder="记录想法、反馈或修改意见…"></textarea><button class="primary">发送到项目记录</button><p class="muted tiny">聊天保留原文；不会自动进入正式简报或调用模型。</p></form>`:''}</aside></div>${toast?`<div class="success" id="toast" style="position:fixed;bottom:18px;left:50%;transform:translateX(-50%);z-index:40;box-shadow:0 5px 25px #0002">${esc(toast)}</div>`:''}`}
function stagePills(){const flags=[!!approvedBrief(),!!project.master_approval,!!project.direction_approval,!!project.storyboard_approval,!!approvedGallery()];return ['简报已确认','母版已确认','主线已选择','分镜已批准','套图已批准'].map((x,i)=>`<span class="stage ${flags[i]?'done':i===flags.indexOf(false)?'current':''}">${flags[i]?'✓':'○'} ${x}</span>`).join('')}
function renderView(){const base=({overview,sources,master,creative,prompts,gallery,video,tasks,delivery,canvas})[view]();return base+(view==='tasks'?providerPanel()+seeanyTasks():view==='sources'?aiControls('facts'):view==='creative'?aiControls('directions'):view==='prompts'?aiControls('prompt')+comparePanel()+seeanyForm('preview'):view==='master'?seeanyForm('master'):view==='gallery'?seeanyForm('plan')+seeanyForm('gallery'):'')}
function overview(){const spent=project.costs.filter(c=>c.status==='确认').reduce((a,c)=>a+Number(c.amount),0);return `<div class="section-head"><div><h2>项目概览</h2><p>下一步从左侧流程继续，所有确认都有记录。</p></div><button class="ghost" data-view="canvas">查看依赖画布 →</button></div><div class="stat-row"><div class="stat"><b>${project.sources.length}</b><span>来源文件</span></div><div class="stat"><b>${project.facts.filter(f=>f.confirmed).length}</b><span>已确认事实</span></div><div class="stat"><b>${project.assets.length}</b><span>创作资产</span></div><div class="stat"><b>¥${spent.toFixed(2)}</b><span>已确认费用</span></div></div><div class="grid2" style="margin-top:14px"><div class="panel"><h3>当前版本</h3>${[['产品简报',approvedBrief()?.number?`v${approvedBrief().number}`:'未确认'],['三视图母版',project.master_approval?`第 ${project.master_approval.group} 组`:'待审核'],['广告方向',project.direction_approval?'已选择':'待选择'],['分镜',project.storyboard_approval?'已批准':'待批准'],['套图',approvedGallery()?'已批准':'待策划']].map(([a,b])=>`<div class="inspector-line row between"><span>${a}</span><b>${b}</b></div>`).join('')}</div><div class="panel"><h3>接入状态</h3><div class="inspector-line">DeepSeek-V4.1-Flash：${capabilities.deepseek?'已检测到环境密钥':'未配置环境密钥'}</div><div class="inspector-line">SeeAny：${esc(capabilities.seeany)}</div><div class="inspector-line">Flova CLI：${capabilities.flova?'已找到命令':'本机未找到命令'}</div><div class="inspector-line">Jev：${esc(capabilities.jev)}</div><div class="warning">SeeAny 可在三视图、提示词和套图页提交；生成费用需逐次核对并批准。</div></div></div><div class="panel"><h3>最近决定</h3>${project.decisions.length?project.decisions.slice(-5).reverse().map(d=>`<div class="inspector-line row between"><span>${esc(d.kind)} · ${esc(d.choice)}</span><span class="muted tiny">${fmt(d.at)}</span></div>`).join(''):empty('尚无审核记录','从导入资料开始。')}</div>`}
function sources(){return `<div class="section-head"><div><h2>资料与产品事实</h2><p>原始文件保持不变，只有逐项确认的已知事实进入新简报版本。</p></div><button class="primary" data-click="upload-source">＋ 导入商家资料</button></div><div class="file-drop" id="dropzone">将图片、截图、TXT、MD、CSV、JSON 或 DOCX 拖到这里，或点击上方导入</div><div class="grid2" style="margin-top:14px"><div><div class="panel"><h3>原始资料 <span class="tag">${project.sources.length}</span></h3><div class="card-list">${project.sources.length?project.sources.map(s=>`<div class="item">${s.mime.startsWith('image/')?`<img src="${fileUrl(s.id)}">`:'<div class="thumb" style="display:grid;place-items:center">▤</div>'}<div class="item-main"><h4>${esc(s.name)}</h4><p>${badge(s.parse_status,s.text?'green':'orange')} · ${(s.size/1024).toFixed(0)} KB</p>${s.text?`<details><summary class="tiny">查看提取文本</summary><p style="white-space:pre-wrap;max-height:150px;overflow:auto">${esc(s.text.slice(0,2000))}</p></details>`:''}</div><a class="smallbtn" href="${fileUrl(s.id)}" target="_blank">查看</a></div>`).join(''):empty('暂无资料','拖入商品照片或文档。')}</div></div><div class="panel"><h3>添加候选事实</h3><form id="fact-form">${select('field','类型',['规格','卖点','使用场景','限制','外观','其他'])}${area('value','内容','','例如：机身为白色，具体型号待商家核实')}${select('status','证据状态',['已知事实','待核实','创意假设'])}<div class="field"><label>来源文件</label><select name="source_id"><option value="">人工确认 / 暂无文件</option>${project.sources.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><button class="primary">添加候选</button></form><div class="warning">无法可靠解析的文件标为“需人工查看”；请依据原件逐项核对。</div></div></div><div class="panel"><div class="row between"><h3>事实审核 <span class="tag">${project.facts.length}</span></h3><button class="primary" data-click="brief-confirm" ${!project.facts.some(f=>f.confirmed)?'disabled':''}>确认新简报版本</button></div><div class="card-list">${project.facts.length?project.facts.map(f=>`<div class="item fact ${f.confirmed?'confirmed':''}"><div class="item-main"><h4>${esc(f.field)} · ${esc(f.value)}</h4><p>${badge(f.status,f.status==='已知事实'?'green':f.status==='待核实'?'orange':'blue')} ${f.source_ids.map(id=>esc(source(id)?.name||'人工确认')).join('、')||'人工确认'}</p></div>${f.status==='待核实'?`<button class="smallbtn" data-fact-verify="${f.id}">核对为已知事实</button>`:''}${f.status==='已知事实'?`<button class="smallbtn" data-fact="${f.id}">${f.confirmed?'撤回':'确认事实'}</button>`:''}</div>`).join(''):empty('尚无候选事实','请先添加并确认事实。')}</div></div><div class="panel"><h3>已确认简报版本</h3>${project.brief_versions.length?project.brief_versions.map(b=>`<div class="inspector-line">v${b.number} · ${b.facts.length} 条事实 · ${fmt(b.created)} ${badge(b.id===approvedBrief()?.id?'当前版本':'历史版本',b.id===approvedBrief()?.id?'green':'')}</div>`).join(''):empty('尚无简报版本','确认事实后创建。')}</div>`}
function master(){const groups=[1,2];return `<div class="section-head"><div><h2>三视图母版</h2><p>从真实照片建立候选；整体批准不代表推断结构已经核实。</p></div><button class="ghost" data-click="upload-asset">导入候选图</button></div>${!approvedBrief()?'<div class="warning">先在“资料与事实”中确认产品简报。</div>':''}<div class="grid2">${groups.map(g=>`<div class="panel"><div class="row between"><h3>候选组 ${g}</h3><button class="smallbtn" data-master-approve="${g}" ${!project.masters.some(m=>m.group===g)?'disabled':''}>批准这组</button></div><div class="assets">${project.masters.filter(m=>m.group===g).map(m=>{const a=asset(m.asset_id);return `<div class="asset-card"><img src="${assetSrc(a)}" data-zoom="${assetSrc(a)}"><h4>${esc(m.view)} ${m.inferred?badge('含推断','orange'):badge('有依据','green')}</h4><div class="tiny muted">依据：${m.source_ids.map(id=>esc(source(id)?.name||'')).join('、')||'未标注'}</div></div>`}).join('')||empty('未添加视角','从下方已导入图中选择。')}</div>${project.master_approval?.group===g?'<div class="success">当前创作母版</div>':''}</div>`).join('')}</div><div class="panel"><h3>加入母版视角</h3><form id="master-form" class="grid2"><div>${select('group','候选组',['1','2'])}${select('view','视角',['正面','侧面','背面','顶部','其他'])}</div><div><div class="field"><label>候选图片</label><select name="asset_id">${project.assets.filter(a=>source(a.source_id)?.mime.startsWith('image/')).map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label>依据原始照片</label><select name="source_id"><option value="">无直接照片依据</option>${project.sources.filter(s=>s.mime.startsWith('image/')).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><label class="tiny"><input type="checkbox" name="inferred"> 包含 AI 推断结构</label><p><button class="primary" ${!approvedBrief()?'disabled':''}>加入视角</button></p></div></form></div><div class="panel"><h3>结构细节单独核实</h3><form id="detail-form" class="row"><input name="description" class="search" placeholder="例如：背部进风口位置" required><select name="source_id" class="search"><option value="">无证据，仍为推断</option>${project.sources.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select><label class="tiny"><input type="checkbox" name="verified"> 已核实</label><button class="smallbtn">记录</button></form>${project.details.map(d=>`<div class="inspector-line">${esc(d.description)} ${badge(d.verified?'已核实':'推断，禁止当卖点',d.verified?'green':'orange')}</div>`).join('')}</div>`}
function creative(){const script=latest(project.script_versions),board=latest(project.storyboard_versions);return `<div class="section-head"><div><h2>广告策划与分镜</h2><p>先选择主线，再审批脚本和完整分镜。</p></div></div>${!project.master_approval?'<div class="warning">批准母版后才能新增创意方向。</div>':''}<div class="panel"><h3>广告切入点 ${badge(project.directions.length+'/3 个建议','blue')}</h3><div class="grid3">${project.directions.map(d=>`<div class="item" style="display:block"><h4>${esc(d.title)}</h4><p>目标用户：${esc(d.audience)}</p><p>开头：${esc(d.opening)}</p><p>核心卖点：${esc(d.selling_point)}</p><p>结尾：${esc(d.ending)}</p><div style="margin-top:10px"><button class="smallbtn" data-direction="${d.id}">${project.direction_approval===d.id?'✓ 当前主线':'选择主线'}</button></div></div>`).join('')||empty('暂无广告方向','记录三个不同切入点以便比较。')}</div><details style="margin-top:14px"><summary>＋ 添加方向</summary><form id="direction-form" class="grid2" style="margin-top:12px"><div>${textField('title','方向标题')}${textField('audience','目标用户')}${textField('opening','开头画面')}</div><div>${textField('selling_point','核心卖点')}${textField('ending','结尾') }<button class="primary" ${!project.master_approval?'disabled':''}>保存方向</button></div></form></details></div><div class="grid2"><div class="panel"><div class="row between"><h3>脚本</h3>${script?`<button class="smallbtn" data-script-approve="${script.id}">${project.script_approval===script.id?'✓ 已批准':'批准此版本'}</button>`:''}</div><p class="muted tiny">根据已确认简报与当前广告主线生成可编辑脚本草稿。</p><button class="smallbtn" data-ai="script" ${!providerSettings.deepseek_configured||!project.direction_approval?'disabled':''}>DeepSeek 生成脚本 · 预估费用</button><form id="script-form">${area('text','脚本文案',script?.text||'','约 15 秒，默认竖屏，静音可理解') }<button class="primary" ${!project.direction_approval?'disabled':''}>保存新脚本版本</button></form>${project.script_versions.map((s,i)=>`<div class="inspector-line tiny">v${i+1} · ${fmt(s.created)} ${s.id===project.script_approval?badge('已批准','green'):''}</div>`).join('')}</div><div class="panel"><div class="row between"><h3>分镜</h3>${board?`<button class="smallbtn" data-board-approve="${board.id}">${project.storyboard_approval===board.id?'✓ 已批准':'批准整版分镜'}</button>`:''}</div><p class="muted tiny">每行一个镜头：画面描述 | 时长秒数 | 字幕。保存会创建不可覆盖的新版本。</p><button class="smallbtn" data-ai="storyboard" ${!providerSettings.deepseek_configured||!project.script_approval?'disabled':''}>DeepSeek 生成分镜 · 预估费用</button><form id="board-form">${area('shots','镜头列表',board?.shots.map(s=>`${s.description} | ${s.duration} | ${s.caption||''}`).join('\n')||'','产品近景 | 3 | 一眼看见品质') }<button class="primary" ${!project.script_approval?'disabled':''}>保存新分镜版本</button></form>${board?`<div class="inspector-line">当前 ${board.shots.length} 镜 · ${board.shots.reduce((n,s)=>n+Number(s.duration),0)} 秒 · 9:16</div>`:''}${project.storyboard_versions.map((s,i)=>`<div class="inspector-line tiny">v${i+1} · ${fmt(s.created)} ${s.id===project.storyboard_approval?badge('已批准','green'):''}</div>`).join('')}</div></div>`}
function prompts(){const p=currentPrompt?project.prompts.find(x=>x.id===currentPrompt):latest(project.prompts);return `<div class="section-head"><div><h2>提示词与选图</h2><p>字段化编辑、版本追溯和真实性审核。</p></div><button class="ghost" data-click="upload-asset">＋ 导入 GPT / 本地生成图</button></div><div class="grid2"><div class="panel"><h3>提示词卡片</h3><p class="muted tiny">根据已确认简报生成字段化提示词草稿，保存后仍可逐项编辑。</p><button class="smallbtn" data-ai="prompt_generate" ${!providerSettings.deepseek_configured||!approvedBrief()?'disabled':''}>DeepSeek 生成提示词 · 预估费用</button><form id="prompt-form">${['identity|产品身份与保持特征','scene|场景','composition|构图','lighting|光线','style|风格','ratio|画幅','prohibited|禁止变化项','purpose|目标用途'].map(x=>{const [k,label]=x.split('|');return area(k,label,p?.fields[k]||'')}).join('')}<button class="primary">保存为新版本</button></form></div><div class="panel"><h3>完整提示词</h3><pre style="white-space:pre-wrap;line-height:1.7;font-size:12px">${esc(p?.text||'填写左侧字段后生成。')}</pre><h3>历史版本</h3>${project.prompts.slice().reverse().map((x,i)=>`<div class="inspector-line"><button class="smallbtn" data-prompt="${x.id}">v${project.prompts.length-i}</button> ${fmt(x.created)} ${x.parent_id?'← 基于前版修改':''}</div>`).join('')||empty('暂无提示词版本','保存第一版后可比较字段差异。')}${p?.parent_id?promptDiff(p):''}</div></div><div class="panel"><h3>候选图与当前采用资产</h3><div class="assets">${project.assets.filter(a=>source(a.source_id)?.mime.startsWith('image/')).map(a=>`<div class="asset-card"><img src="${assetSrc(a)}" data-zoom="${assetSrc(a)}"><h4>${esc(a.name)}</h4>${badge(a.review,a.review==='通过真实性'?'green':a.review==='废图'?'red':'orange')} ${Object.values(project.adopted_assets).includes(a.id)?badge('当前采用','green'):''}<div class="tiny muted">${a.prompt_id?'提示词 '+a.prompt_id:'手动导入'}${a.parent_id?' · 子版本':''}</div><div class="actions"><button class="smallbtn" data-compare="${a.id}">并排比较</button><button class="smallbtn" data-review="${a.id}:pass">真实性通过</button><button class="smallbtn" data-review="${a.id}:reject">废图</button><button class="smallbtn" data-adopt="${a.id}" ${a.review!=='通过真实性'?'disabled':''}>采用</button><button class="smallbtn" data-child="${a.id}">基于此图导入</button></div></div>`).join('')||empty('暂无候选图','导入已有图片，再进行真实性审核。')}</div></div>`}
function promptDiff(p){const parent=project.prompts.find(x=>x.id===p.parent_id);if(!parent)return '';const changes=Object.keys(p.fields).filter(k=>p.fields[k]!==parent.fields[k]);return `<div class="warning">相对父版本修改：${changes.map(k=>esc(k)).join('、')||'无字段变化'}</div>`}
function gallery(){const g=galleryDraft||latest(project.gallery);return `<div class="section-head"><div><h2>电商套图</h2><p>默认六张；图片与可编辑文字层分别保存。</p></div><div class="row"><button class="ghost" data-click="gallery-new" ${!project.master_approval?'disabled':''}>＋ 新建六张方案</button>${g?`<button class="primary" data-gallery-approve="${g.id}">${g.approved?'✓ 已批准':'批准套图方案'}</button>`:''}</div></div>${!project.master_approval?'<div class="warning">批准母版后才可策划套图。</div>':''}${g?`<div class="panel"><div class="row between"><h3>套图方案 · ${g.items.length} 张</h3>${badge(g.approved?'已批准':'待审核',g.approved?'green':'orange')}</div><div class="card-list">${g.items.map((item,i)=>`<div class="item"><div class="thumb" style="display:grid;place-items:center;overflow:hidden">${item.asset_id&&asset(item.asset_id)?`<img src="${assetSrc(asset(item.asset_id))}" style="width:100%;height:100%;object-fit:cover">`:'▧'}</div><div class="item-main"><h4>${i+1}. ${esc(item.kind)} <button class="smallbtn" data-gallery-edit="${i}">编辑</button></h4><p>${esc(item.title||'未设置标题')} · ${esc(item.prompt||'未填写单张提示词')}</p></div><button class="smallbtn" data-gallery-up="${i}">↑</button><button class="smallbtn" data-gallery-down="${i}">↓</button><button class="smallbtn danger" data-gallery-remove="${i}">×</button></div>`).join('')}</div><button class="smallbtn" data-click="gallery-add" style="margin-top:12px">＋ 增加图片</button><button class="primary" data-click="gallery-save" style="margin-top:12px">保存为新方案版本</button></div><div id="gallery-editor"></div>`:empty('尚无套图方案','新建默认六张结构，再逐张调整类型、顺序、提示词和文字。')}<div class="warning">拼多多实际尺寸、比例及文件大小，请以试点商家后台当前要求核对。</div>`}
function video(){const total=project.clips.reduce((a,c)=>a+(Number(c.end)-Number(c.start))/Number(c.speed),0);return `<div class="section-head"><div><h2>视频收尾</h2><p>导入 Flova 镜头后可裁剪、排序、变速并导出竖屏成片；目标约 15 秒。</p></div><button class="ghost" data-click="upload-video">＋ 导入 Flova 媒体</button></div>${flovaPanel()}<div class="panel"><h3>Flova 项目</h3><form id="external-form" class="grid2"><div>${textField('flova_project_id','项目 ID',project.external.flova_project_id)}</div><div>${textField('flova_url','Flova 网页地址',project.external.flova_url)}<button class="smallbtn">保存关联</button></div></form>${project.external.flova_url?`<a class="smallbtn" href="${esc(project.external.flova_url)}" target="_blank" rel="noopener">在 Flova 中精剪 ↗</a>`:''}<div class="warning">可手动关联已有项目。Flova 创作结果需人工审核，再导回需要的媒体。</div></div><div class="grid2"><div class="panel"><h3>加入镜头</h3><form id="clip-form"><div class="field"><label>视频素材</label><select name="asset_id">${project.assets.filter(a=>source(a.source_id)?.mime.startsWith('video/')).map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></div><div class="grid3">${textField('start','起点（秒）','0')}${textField('end','终点（秒）','3')}${textField('speed','速度','1')}</div>${textField('caption','字幕层')}<button class="primary">加入时间线</button></form></div><div class="panel"><h3>总时长预览</h3><div style="font-size:42px;font-weight:700;color:#21553e">${total.toFixed(1)} <small style="font-size:15px">秒</small></div><div class="progress"><i style="width:${Math.min(100,total/15*100)}%"></i></div><p class="muted tiny">竖屏 9:16 · 静音可理解 · 速度 0.5–2.0。原音频使用 FFmpeg atempo 保持音高。</p>${project.clips.length?`<a class="primary" style="display:inline-block;text-decoration:none" href="/api/projects/${project.id}/video-export">导出本地收尾 MP4</a>`:''}</div></div><div class="panel"><h3>镜头顺序</h3>${project.clips.map((c,i)=>{const a=asset(c.asset_id);return `<div class="item"><div class="item-main"><h4>${i+1}. ${esc(a?.name||'镜头')}</h4><p>${c.start}–${c.end}s · ${c.speed}× · ${((c.end-c.start)/c.speed).toFixed(1)}s · ${esc(c.caption)}</p></div><button class="smallbtn" data-clip-up="${i}">↑</button><button class="smallbtn" data-clip-down="${i}">↓</button><button class="smallbtn danger" data-clip-remove="${i}">×</button></div>`}).join('')||empty('尚无镜头','从 Flova 导回视频素材并加入时间线。')}</div>`}
function tasks(){const spent=project.costs.filter(c=>c.status==='确认').reduce((a,c)=>a+Number(c.amount),0);return `<div class="section-head"><div><h2>任务与费用</h2><p>任何计费任务在提交前都要有可靠估算和明确审核。</p></div></div><div class="grid2"><div class="panel"><h3>预算设置</h3><form id="settings-form"><div class="grid2">${textField('total_budget','项目总预算（元）',project.settings.total_budget)}${textField('unattended_limit','无人值守单次额度（元）',project.settings.unattended_limit)}</div><h4>阶段预留</h4><div class="grid2">${stages.map((s,i)=>textField('stage'+i,s,project.settings.stage_reserve[s])).join('')}</div><button class="primary">保存预算</button></form><p class="muted tiny">已确认花费 ¥${spent.toFixed(2)}；费用按供应商记录。此处金额由用户填写，不代表供应商实时价格。</p></div><div class="panel"><h3>登记待审核任务</h3><form id="task-form">${select('stage','阶段',stages)}${select('provider','供应商',['SeeAny','Flova','DeepSeek','Jev'])}${textField('description','任务说明')}${textField('estimate','可靠费用估算（元）','','未知则留空并阻止执行')}<label class="tiny"><input type="checkbox" name="unattended"> 计划无人值守</label><p><button class="primary">检查并登记</button></p></form><div class="warning">SeeAny 任务在相应创作页面明确批准后提交。断网或重启后先同步远端状态，不自动补发。</div></div></div><div class="panel"><h3>任务列表</h3>${project.tasks.map(t=>`<div class="item"><div class="item-main"><h4>${esc(t.description||t.stage)} ${badge(t.status,t.status==='费用阻止'?'red':t.status==='完成'?'green':'orange')}</h4><p>${esc(t.provider)} · ${esc(t.stage)} · ${t.estimate==null?'费用未知':'预计 ¥'+t.estimate} · 尝试 ${t.attempts} 次</p><p>${esc(t.reason)}</p><p class="mono">本地 ${t.id} · 幂等 ${t.idempotency_key} ${t.remote_id?'· 远端 '+esc(t.remote_id):''}</p></div><button class="smallbtn" data-task-edit="${t.id}">更新</button></div>`).join('')||empty('暂无任务','登记任务后先核对价格与预算。')}</div><div class="panel"><h3>费用记录</h3>${project.costs.map(c=>`<div class="inspector-line row between"><span>${esc(c.provider)} · ${esc(c.stage)}</span><b>¥${Number(c.amount).toFixed(2)}</b></div>`).join('')||empty('暂无费用记录','实际扣费后按供应商登记。')}</div>`}
function delivery(){return `<div class="section-head"><div><h2>交付与备份</h2><p>带走文件、来源和可追溯版本。</p></div></div><div class="grid2"><div class="panel"><h3>交付包</h3><p class="muted">包含已确认脚本、采用提示词、来源清单、可用套图 PNG/SVG 与导入的视频素材。</p><a class="primary" style="display:inline-block;text-decoration:none" href="/api/projects/${project.id}/export">下载交付 ZIP</a><div class="warning">未导入的 Flova 成片或未关联图片不会出现在交付包中。正式交付前请检查文件和拼多多后台要求。</div></div><div class="panel"><h3>完整项目备份</h3><p class="muted">包含原始文件、版本、画布、审核、费用和项目状态；不包含密钥。</p><a class="ghost" style="display:inline-block;text-decoration:none" href="/api/projects/${project.id}/backup">下载完整备份</a><button class="ghost" data-click="restore" style="margin-left:8px">恢复备份</button></div></div><div class="panel"><h3>项目管理</h3><div class="row"><button class="ghost" data-click="archive">${project.archived?'取消归档':'归档项目'}</button><button class="danger" data-click="delete">彻底删除项目</button></div></div>`}
function chatView(){return `<div class="muted tiny" style="margin-bottom:18px">完整创作讨论记录。正式生成只读取已确认状态。</div>${project.chat.map(m=>`<div class="chat-message ${m.role==='user'?'user':''}">${esc(m.text)}<div class="muted tiny" style="margin-top:5px">${fmt(m.at)}</div></div>`).join('')||empty('开始记录创作想法','例如：只换场景、保持产品角度。当前为本地记录。')}`}
function inspectorView(){const n=graphNodes().find(x=>x.id===selectedNode);if(!n)return empty('选择画布节点','查看输入版本、状态和依赖关系。');return `<h3>${esc(n.label)}</h3><div class="inspector-line"><b>类型</b>${esc(n.stage)}</div><div class="inspector-line"><b>状态</b>${esc(n.status)}</div><div class="inspector-line"><b>版本引用</b><span class="mono">${esc(n.ref||'—')}</span></div><div class="inspector-line"><b>输入依赖</b>${graphEdges().filter(e=>e.target===n.id).map(e=>esc(graphNodes().find(x=>x.id===e.source)?.label||'')).join('、')||'无'}</div><div class="inspector-line"><b>下游节点</b>${graphEdges().filter(e=>e.source===n.id).map(e=>esc(graphNodes().find(x=>x.id===e.target)?.label||'')).join('、')||'无'}</div><div class="warning">节点连接只记录依赖，不触发计费。</div>`}

function graphNodes(){const definitions=[['source','原始资料',project.sources.length?'完成':'等待',null],['brief','产品简报',approvedBrief()?'完成':'待审核',approvedBrief()?.id],['master','三视图母版',project.master_approval?'完成':'待审核',project.master_approval?.group],['direction','广告主线',project.direction_approval?'完成':'等待',project.direction_approval],['script','已确认脚本',project.script_approval?'完成':'等待',project.script_approval],['storyboard','完整分镜',project.storyboard_approval?'完成':'等待',project.storyboard_approval],['prompt','提示词版本',project.prompts.length?'完成':'等待',latest(project.prompts)?.id],['asset','采用资产',Object.keys(project.adopted_assets).length?'完成':'等待',Object.values(project.adopted_assets).join(',')],['gallery','电商套图',approvedGallery()?'完成':'等待',approvedGallery()?.id],['video','视频镜头',project.clips.length?'完成':'等待',project.external.flova_project_id],['delivery','交付物',approvedGallery()&&project.clips.length?'待审核':'等待',null]];const loc={source:[70,110],brief:[320,110],master:[570,110],direction:[820,110],script:[1070,110],storyboard:[1320,110],prompt:[570,320],asset:[820,320],gallery:[1070,320],video:[1570,110],delivery:[1590,320]};return definitions.map(([stage,label,status,ref])=>{const saved=project.nodes.find(n=>n.id===stage)||{};return {id:stage,stage,label,status,ref,x:saved.x??loc[stage][0],y:saved.y??loc[stage][1],stale:saved.stale||false}})}
function graphEdges(){const base=[['source','brief'],['brief','master'],['master','direction'],['direction','script'],['script','storyboard'],['master','prompt'],['prompt','asset'],['master','asset'],['asset','gallery'],['asset','video'],['storyboard','video'],['gallery','delivery'],['video','delivery']].map(([source,target])=>({id:source+'-'+target,source,target}));return [...base,...project.edges.filter(e=>!base.some(b=>b.source===e.source&&b.target===e.target))]}
function canvas(){const nodes=graphNodes(),edges=graphEdges();return `<div class="section-head"><div><h2>创作依赖画布</h2><p>拖动节点、缩放画布；线条表示真实输入关系。</p></div><button class="ghost" data-click="canvas-reset">复位视图</button></div><div class="canvas-shell" id="canvas-shell"><div class="canvas-toolbar"><button data-click="zoom-in">＋</button><button data-click="zoom-out">－</button><button data-click="canvas-reset">适合屏幕</button></div><div class="canvas-viewport" id="canvas-viewport" style="transform:translate(${canvasPan.x}px,${canvasPan.y}px) scale(${canvasScale})"><svg class="canvas-edges" width="1900" height="600">${edges.map(e=>{let a=nodes.find(n=>n.id===e.source),b=nodes.find(n=>n.id===e.target);if(!a||!b)return '';const sx=a.x+184,sy=a.y+45,tx=b.x,ty=b.y+45;return `<path d="M ${sx} ${sy} C ${sx+70} ${sy}, ${tx-70} ${ty}, ${tx} ${ty}"/>`}).join('')}</svg>${nodes.map(n=>`<div class="canvas-node ${selectedNode===n.id?'selected':''} ${n.stale?'stale':''}" data-node="${n.id}" style="left:${n.x}px;top:${n.y}px"><span class="dot ${n.status==='完成'?'done':n.status==='等待'?'':'pending'}"></span><small>${esc(n.stage).toUpperCase()}</small><b>${esc(n.label)}</b><span>${esc(n.status)} ${n.stale?'· 上游已变更':''}</span></div>`).join('')}</div></div><div class="panel" style="margin-top:14px"><h3>连接依赖</h3><p class="muted tiny">只能连接兼容的节点类型；新增连线仅改变草稿关系。</p><form id="edge-form" class="row"><select name="source" class="search" style="max-width:190px">${nodes.map(n=>`<option value="${n.id}">${esc(n.label)}</option>`).join('')}</select><span>→</span><select name="target" class="search" style="max-width:190px">${nodes.map(n=>`<option value="${n.id}">${esc(n.label)}</option>`).join('')}</select><button class="smallbtn">添加连线</button></form></div>`}

function bind(){ $$('[data-view]').forEach(el=>el.onclick=()=>{view=el.dataset.view;render()});$$('[data-right]').forEach(el=>el.onclick=()=>{rightTab=el.dataset.right;render()});$$('[data-open]').forEach(el=>el.onclick=async()=>{try{project=await api('/projects/'+el.dataset.open);localStorage.setItem(key,project.id);view='overview';render()}catch(e){error(e)}});$$('[data-click]').forEach(el=>el.onclick=()=>click(el.dataset.click));$$('[data-zoom]').forEach(el=>el.onclick=()=>zoom(el.dataset.zoom));$$('[data-ai]').forEach(el=>el.onclick=()=>requestAi(el.dataset.ai));bindForms();bindActions();bindFlova();if(view==='canvas')bindCanvas();const drop=$('#dropzone');if(drop){drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging')};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');handleFiles([...e.dataTransfer.files],'source')}}const search=$('#project-search');if(search)search.oninput=async()=>{$('#project-list').innerHTML=projectCards(await api('/projects?q='+encodeURIComponent(search.value)));$$('[data-open]').forEach(el=>el.onclick=async()=>{project=await api('/projects/'+el.dataset.open);localStorage.setItem(key,project.id);render()})}}
async function click(name){try{if(name==='create-project'){createOpen=true;render()}else if(name==='close-create'){createOpen=false;render()}else if(name==='home'){project=null;localStorage.removeItem(key);projects=await api('/projects');render()}else if(name==='upload'||name==='upload-source'||name==='upload-asset'||name==='upload-video'){uploadMode=name==='upload-video'?'video':name==='upload-asset'?'asset':name==='upload-source'?'source':view==='prompts'||view==='master'?'asset':'source';$('#upload').click()}else if(name==='restore')$('#restore').click();else if(name==='brief-confirm'){await act('brief_confirm');notify('新简报版本已确认')}else if(name==='gallery-new'){await act('gallery');notify('已建立默认六张方案')}else if(name==='gallery-add'){galleryDraft=structuredClone(latest(project.gallery));galleryDraft.items.push({id:crypto.randomUUID(),kind:'新增图片',prompt:'',asset_id:null,title:'',subtitle:'',x:50,y:10});render()}else if(name==='gallery-save'){if(!galleryDraft)galleryDraft=structuredClone(latest(project.gallery));await act('gallery',{items:galleryDraft.items});galleryDraft=null;notify('新套图方案版本已保存')}else if(name==='archive'){await act('archive',{archived:!project.archived});notify(project.archived?'已归档':'已取消归档')}else if(name==='delete'){const value=prompt(`彻底删除将移除所有本地文件。请输入项目名确认：${project.name}`);if(value!==project.name)return;await api(`/projects/${project.id}/delete`,{confirm:value});project=null;localStorage.removeItem(key);projects=await api('/projects');render()}else if(name==='zoom-in'){canvasScale=Math.min(1.8,canvasScale+.15);render()}else if(name==='zoom-out'){canvasScale=Math.max(.35,canvasScale-.15);render()}else if(name==='canvas-reset'){canvasScale=.68;canvasPan={x:20,y:50};render()}else if(name==='ai-cancel'){aiPending=null;render()}else if(name==='ai-run'){await runAi()}}catch(e){error(e)}}
async function handleFiles(files,mode){for(const f of files){try{const b64=await fileBase64(f);if(mode==='source'){await act('source',{name:f.name,data:b64})}else{await act('asset',{name:f.name,data:b64,origin:mode==='video'?'Flova 导入':'手动导入',kind:mode==='video'?'镜头视频':'候选图',prompt_id:currentPrompt||latest(project.prompts)?.id||null,parent_id:uploadParentAsset})}}catch(e){uploadParentAsset=null;error(e);return}}uploadParentAsset=null;notify(`已导入 ${files.length} 个文件`)}
function fileBase64(f){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(f)})}
function zoom(url){const el=document.createElement('div');el.className='overlay';el.innerHTML=`<button>×</button><img src="${url}">`;el.onclick=()=>el.remove();document.body.append(el)}
function bindForms(){const on=(id,fn)=>{const e=$('#'+id);if(e)e.onsubmit=async ev=>{ev.preventDefault();try{await fn(formData(e),e)}catch(x){error(x)}}};on('create-form',async d=>{project=await api('/projects',{name:d.name});localStorage.setItem(key,project.id);projects=await api('/projects');createOpen=false;view='sources';render()});on('fact-form',async d=>{await act('fact',{field:d.field,value:d.value,status:d.status,source_ids:d.source_id?[d.source_id]:[]});notify('候选事实已添加')});on('master-form',async d=>{await act('master',{group:d.group,view:d.view,asset_id:d.asset_id,source_ids:d.source_id?[d.source_id]:[],inferred:!!d.inferred});notify('已加入母版视角')});on('detail-form',async d=>{await act('detail',{description:d.description,source_ids:d.source_id?[d.source_id]:[],verified:!!d.verified});notify('细节已记录')});on('direction-form',async d=>{await act('direction',d);notify('广告方向已添加')});on('script-form',async d=>{await act('script',d);notify('脚本新版本已保存')});on('board-form',async d=>{const shots=d.shots.split('\n').filter(Boolean).map(line=>{const [description,duration,caption]=line.split('|').map(s=>s?.trim());return {description,duration:Number(duration)||3,caption:caption||'',ratio:'9:16',reference_ids:[],detail_ids:[]}});await act('storyboard',{shots});notify('分镜新版本已保存')});on('prompt-form',async d=>{await act('prompt',{...d,parent_id:currentPrompt||latest(project.prompts)?.id||null});currentPrompt=latest(project.prompts)?.id;notify('提示词新版本已保存')});on('clip-form',async d=>{await act('clip',d);notify('镜头已加入')});on('external-form',async d=>{await act('external',d);notify('Flova 项目关联已保存')});on('settings-form',async d=>{await act('settings',{total_budget:d.total_budget,unattended_limit:d.unattended_limit,stage_reserve:Object.fromEntries(stages.map((s,i)=>[s,d['stage'+i]]))});notify('预算已保存')});on('task-form',async d=>{const r=await act('task',{...d,unattended:!!d.unattended});notify(r.status==='费用阻止'?`已阻止：${r.reason}`:'已登记待审核任务')});on('chat-form',async d=>{if(!d.text.trim())return;await act('chat',{text:d.text,role:'user'});$('.right-body').scrollTop=$('.right-body').scrollHeight});on('edge-form',async d=>{await act('edge',d);notify('依赖连线已保存')});on('provider-form',async d=>{providerSettings=await api('/provider-settings',d);capabilities=await api('/capabilities');notify('本机供应商设置已保存，密钥不进入项目备份')});}
function bindActions(){const each=(selector,fn)=>$$(selector).forEach(el=>el.onclick=()=>fn(el));each('[data-fact]',async el=>{try{const f=project.facts.find(x=>x.id===el.dataset.fact);await act('fact_review',{id:f.id,confirmed:!f.confirmed})}catch(e){error(e)}});each('[data-fact-verify]',async el=>{try{await act('fact_edit',{id:el.dataset.factVerify,status:'已知事实',note:'人工对照原始资料'});notify('状态已改为已知事实，请再确认纳入简报')}catch(e){error(e)}});each('[data-master-approve]',async el=>{try{await act('master_approve',{group:Number(el.dataset.masterApprove)});notify('母版整体已批准，推断细节仍须单独核实')}catch(e){error(e)}});each('[data-direction]',async el=>{try{await act('direction_approve',{id:el.dataset.direction});notify('广告主线已选择')}catch(e){error(e)}});each('[data-script-approve]',async el=>{try{await act('script_approve',{id:el.dataset.scriptApprove});notify('脚本已批准')}catch(e){error(e)}});each('[data-board-approve]',async el=>{try{await act('storyboard_approve',{id:el.dataset.boardApprove});notify('分镜已批准')}catch(e){error(e)}});each('[data-prompt]',el=>{currentPrompt=el.dataset.prompt;render()});each('[data-compare]',el=>{const id=el.dataset.compare;compareIds=compareIds.includes(id)?compareIds.filter(x=>x!==id):[...compareIds.slice(-1),id];render()});each('[data-ref-save]',async el=>{try{const id=el.dataset.refSave;const sid=el.closest('.reference-form').querySelector('select').value;await act('asset_reference',{id,source_ids:sid?[sid]:[]});notify('参考实拍已关联')}catch(e){error(e)}});each('[data-review]',async el=>{try{const [id,choice]=el.dataset.review.split(':');const reason=choice==='reject'?prompt('废图原因（结构错误、场景不真实、卖点不清楚等）')||'未说明':'';await act('asset_review',{id,choice:choice==='reject'?'废图':'通过真实性',reason})}catch(e){error(e)}});each('[data-child]',el=>{uploadParentAsset=el.dataset.child;uploadMode='asset';$('#upload').click()});each('[data-adopt]',async el=>{try{await act('adopt',{id:el.dataset.adopt,slot:'产品主体'});notify('当前采用资产已更新')}catch(e){error(e)}});each('[data-gallery-approve]',async el=>{try{if(galleryDraft){notify('请先保存方案版本');return}await act('gallery_approve',{id:el.dataset.galleryApprove});notify('套图方案已批准')}catch(e){error(e)}});each('[data-gallery-edit]',el=>galleryEditor(Number(el.dataset.galleryEdit)));each('[data-gallery-up]',el=>moveGallery(Number(el.dataset.galleryUp),-1));each('[data-gallery-down]',el=>moveGallery(Number(el.dataset.galleryDown),1));each('[data-gallery-remove]',el=>{galleryDraft=structuredClone(galleryDraft||latest(project.gallery));galleryDraft.items.splice(Number(el.dataset.galleryRemove),1);render()});each('[data-clip-up]',el=>moveClip(Number(el.dataset.clipUp),-1));each('[data-clip-down]',el=>moveClip(Number(el.dataset.clipDown),1));each('[data-clip-remove]',el=>moveClip(Number(el.dataset.clipRemove),0,true));each('[data-task-edit]',el=>taskEdit(el.dataset.taskEdit));const upload=$('#upload');upload.onchange=()=>{handleFiles([...upload.files],uploadMode);upload.value=''};const restore=$('#restore');restore.onchange=async()=>{try{const response=await fetch('/api/restore',{method:'POST',headers:{'Content-Type':'application/zip'},body:restore.files[0]});const data=await response.json();if(!response.ok)throw Error(data.error||'恢复失败');project=data;localStorage.setItem(key,project.id);view='overview';render();notify('备份已恢复，远端任务须重新核对')}catch(e){error(e)}restore.value=''};}
function galleryEditor(index){galleryDraft=structuredClone(galleryDraft||latest(project.gallery));const item=galleryDraft.items[index];$('#gallery-editor').innerHTML=`<div class="panel"><h3>编辑第 ${index+1} 张</h3><form id="gallery-item-form"><div class="grid2"><div>${textField('kind','图片类型',item.kind)}${area('prompt','单张提示词',item.prompt)}<div class="field"><label>底图资产</label><select name="asset_id"><option value="">暂不关联</option>${project.assets.filter(a=>source(a.source_id)?.mime.startsWith('image/')).map(a=>`<option value="${a.id}" ${a.id===item.asset_id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div></div><div>${textField('title','可编辑标题',item.title)}${textField('subtitle','可编辑副标题',item.subtitle)}<div class="grid2">${textField('x','文字水平位置 %',item.x)}${textField('y','文字垂直位置 %',item.y)}</div></div></div><button class="primary">保存本张草稿</button></form></div>`;$('#gallery-item-form').onsubmit=e=>{e.preventDefault();const d=formData(e.target);Object.assign(item,{...d,x:Number(d.x),y:Number(d.y),asset_id:d.asset_id||null});render();notify('本张草稿已更新，请保存新方案版本')}}
function moveGallery(index,delta){galleryDraft=structuredClone(galleryDraft||latest(project.gallery));const next=index+delta;if(next<0||next>=galleryDraft.items.length)return;[galleryDraft.items[index],galleryDraft.items[next]]=[galleryDraft.items[next],galleryDraft.items[index]];render()}
async function moveClip(index,delta,remove=false){try{let clips=structuredClone(project.clips);if(remove)clips.splice(index,1);else{const next=index+delta;if(next<0||next>=clips.length)return;[clips[index],clips[next]]=[clips[next],clips[index]]}await act('clip_update',{clips})}catch(e){error(e)}}
async function taskEdit(id){const t=project.tasks.find(x=>x.id===id);const status=prompt('任务状态：待批准 / 已排队 / 远端运行中 / 待审核 / 完成 / 部分失败 / 失败 / 费用阻止 / 等待网络',t.status);if(!status)return;const remote_id=prompt('供应商任务 ID（没有可留空）',t.remote_id||'');try{await act('task_update',{id,status,remote_id,reason:'人工核对记录'});if(status==='完成'){const amount=prompt('实际费用（元；未知则取消）','');if(amount!==null&&amount!=='')await act('cost',{task_id:id,amount})}}catch(e){error(e)}}
function bindCanvas(){const shell=$('#canvas-shell'),viewport=$('#canvas-viewport');shell.onwheel=e=>{e.preventDefault();canvasScale=Math.max(.35,Math.min(1.8,canvasScale+(e.deltaY<0?.08:-.08)));viewport.style.transform=`translate(${canvasPan.x}px,${canvasPan.y}px) scale(${canvasScale})`};shell.onpointerdown=e=>{if(e.target.closest('.canvas-toolbar'))return;const n=e.target.closest('[data-node]');if(n){selectedNode=n.dataset.node;rightTab='inspector';canvasDrag={type:'node',id:n.dataset.node,startX:e.clientX,startY:e.clientY,x:parseFloat(n.style.left),y:parseFloat(n.style.top),el:n}}else canvasDrag={type:'pan',startX:e.clientX,startY:e.clientY,x:canvasPan.x,y:canvasPan.y};shell.setPointerCapture(e.pointerId)};shell.onpointermove=e=>{if(!canvasDrag)return;const dx=e.clientX-canvasDrag.startX,dy=e.clientY-canvasDrag.startY;if(canvasDrag.type==='pan'){canvasPan={x:canvasDrag.x+dx,y:canvasDrag.y+dy};viewport.style.transform=`translate(${canvasPan.x}px,${canvasPan.y}px) scale(${canvasScale})`}else{canvasDrag.el.style.left=canvasDrag.x+dx/canvasScale+'px';canvasDrag.el.style.top=canvasDrag.y+dy/canvasScale+'px'}};shell.onpointerup=async e=>{if(!canvasDrag)return;const d=canvasDrag;canvasDrag=null;if(d.type==='node'){const x=parseFloat(d.el.style.left),y=parseFloat(d.el.style.top);try{await act('node',{node:{id:d.id,stage:d.id,x,y}})}catch(err){error(err)}}else render()}}
function comparePanel(){const images=compareIds.map(id=>asset(id)).filter(Boolean);return `<div class="panel"><h3>并排挑图 · 先核对产品真实性</h3><p class="muted tiny">在上方候选图点“并排比较”，最多保留两张。为每张图关联对应的原始实拍。</p>${images.length?`<div class="grid2">${images.map(a=>`<div><img src="${assetSrc(a)}" data-zoom="${assetSrc(a)}" style="width:100%;max-height:300px;object-fit:contain;background:#f1f4f0;border-radius:9px"><h4>${esc(a.name)} ${badge(a.review,a.review==='通过真实性'?'green':'orange')}</h4><p class="muted tiny">提示词版本：${esc(a.prompt_id||'无')} · 父资产：${esc(a.parent_id||'无')}</p><div class="row reference-form"><select class="search" style="max-width:230px"><option value="">选择原始实拍</option>${project.sources.filter(s=>s.mime.startsWith('image/')).map(s=>`<option value="${s.id}" ${a.reference_ids.includes(s.id)?'selected':''}>${esc(s.name)}</option>`).join('')}</select><button class="smallbtn" data-ref-save="${a.id}">关联依据</button></div><div class="assets" style="margin-top:10px">${a.reference_ids.map(id=>source(id)).filter(Boolean).map(s=>`<div class="asset-card"><img src="${fileUrl(s.id)}" data-zoom="${fileUrl(s.id)}"><h4>实拍 · ${esc(s.name)}</h4></div>`).join('')||'<span class="muted tiny">尚未关联依据照片</span>'}</div></div>`).join('')}</div>`:empty('尚未选择比较图片','从候选图中选择一到两张。')}</div>`}
function flovaPanel(){const x=project.external||{}, linked=!!x.flova_project_id, pending=['运行中','状态待恢复','待用户确认'].includes(x.flova_run_state);return `<div class="panel"><h3>Flova CLI 创作</h3><p class="muted tiny">CLI 状态：${capabilities.flova?'已安装':'未找到'} · 项目：${linked?esc(x.flova_project_id):'尚未关联'} · 运行：${esc(x.flova_run_state||'未开始')}</p><div class="row"><button class="smallbtn" data-flova="create" ${linked||!capabilities.flova?'disabled':''}>创建 Flova 项目</button><button class="smallbtn" data-flova="info" ${!linked?'disabled':''}>同步项目信息</button><button class="smallbtn" data-flova="recover" ${!linked?'disabled':''}>恢复运行状态</button></div><form id="flova-run-form" style="margin-top:12px">${area('prompt','发送给 Flova 的创作要求',x.flova_last_prompt||'','请写清视频目标、画幅、时长、产品卖点与本轮允许执行的范围')}<p class="muted tiny">点击后会调用已登录的 Flova CLI，可能触发远端生成及费用；CLI 会等待本轮结束。请在 Flova 返回的待确认操作中人工决策；有待确认项时先在 Flova 页面处理。</p><button class="primary" ${!linked||pending?'disabled':''}>确认发送并等待结果</button></form>${x.flova_last_result?`<details open><summary>最近运行结果</summary><pre style="white-space:pre-wrap;max-height:320px;overflow:auto">${esc(JSON.stringify(x.flova_last_result,null,2))}</pre></details>`:''}<div class="row" style="margin-top:12px"><button class="smallbtn" data-flova="readiness" ${!linked?'disabled':''}>检查导出条件</button><button class="smallbtn" data-flova="export" ${!x.flova_export_readiness?.can_export||pending?'disabled':''}>确认导出 Flova 成片</button></div>${x.flova_export_readiness?`<p class="muted tiny">可导出：${x.flova_export_readiness.can_export?'是':'否'} ${esc(x.flova_export_readiness.reason||x.flova_export_readiness.message||'')}</p>`:''}${x.flova_export?.export_url?`<a class="smallbtn" href="${esc(x.flova_export.export_url)}" target="_blank" rel="noopener">打开导出视频 ↗</a>`:''}</div>`}
function bindFlova(){const call=async(kind,body={})=>{const r=await api(`/projects/${project.id}/flova/${kind}`,body);project=r.project;render();notify(`Flova ${kind==='run'?'创作运行已返回':kind==='create'?'项目已创建':kind==='export'?'成片已导出':'状态已更新'}`)};$$('[data-flova]').forEach(el=>el.onclick=async()=>{const kind=el.dataset.flova;if(kind==='export'&&!confirm('确认让 Flova 创建并等待视频导出任务？'))return;el.disabled=true;try{await call(kind)}catch(e){try{project=await api(`/projects/${project.id}`)}catch{}error(e)}});const form=$('#flova-run-form');if(form)form.onsubmit=async e=>{e.preventDefault();const promptText=String(new FormData(form).get('prompt')||'').trim();if(!promptText){error(Error('请填写创作要求'));return}if(!confirm('确认将这段要求发送给 Flova，并等待本轮创作结果？'))return;const button=form.querySelector('button');button.disabled=true;button.textContent='Flova 运行中…';try{await call('run',{prompt:promptText})}catch(err){try{project=await api(`/projects/${project.id}`)}catch{}error(err)}}}
function providerPanel(){return `<div class="panel"><h3>本机供应商设置</h3><p class="muted tiny">DeepSeek 和 SeeAny 密钥优先从项目根目录 .env 或本机环境变量读取，也可在此覆盖为本机设置。密钥不进入项目备份或页面回显。DeepSeek-V4.1-Flash 的 API 模型 ID 为 deepseek-flash。</p><form id="provider-form" class="grid2"><div><div class="field"><label>DeepSeek API Key ${badge(providerSettings.deepseek_configured?'已配置':'未配置',providerSettings.deepseek_configured?'green':'orange')}</label><input type="password" name="deepseek_api_key" autocomplete="off" placeholder="留空则保留现有密钥"></div><div class="field"><label>SeeAny API Key ${badge(providerSettings.seeany_configured?'已配置':'未配置',providerSettings.seeany_configured?'green':'orange')}</label><input type="password" name="seeany_api_key" autocomplete="off" placeholder="推荐改用项目根目录 .env"></div><div class="field"><label>Jev API Key ${badge(providerSettings.jev_configured?'已配置':'未配置',providerSettings.jev_configured?'green':'orange')}</label><input type="password" name="jev_api_key" autocomplete="off" placeholder="仅用于未来旁路判断"></div></div><div>${textField('input_cny_per_m','DeepSeek 输入每百万 token 价格（人民币）',providerSettings.input_cny_per_m)}${textField('output_cny_per_m','DeepSeek 输出每百万 token 价格（人民币）',providerSettings.output_cny_per_m)}<div class="warning">请按当前官方价格填写。工作台以 UTF-8 字节数加开销估算文本输入上界，并按生成类型限制输出 token；每次调用仍须单独批准。图片输入暂不启用。</div><button class="primary">保存本机设置</button></div></form></div>`}
function aiControls(kind){if(kind==='facts')return `<div class="panel"><h3>DeepSeek 文本提取</h3><p class="muted tiny">只使用所选文件的可读文本，结果一律标为待核实。</p><div class="row"><select id="ai-source" class="search" style="max-width:350px">${project.sources.filter(s=>s.text).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select><button class="smallbtn" data-ai="facts" ${!providerSettings.deepseek_configured||!project.sources.some(s=>s.text)?'disabled':''}>预估费用</button></div></div>`;if(kind==='directions')return `<div class="panel"><h3>DeepSeek 提出三个方向</h3><p class="muted tiny">仅引用已确认简报。生成后仍由你选择主线。</p><button class="smallbtn" data-ai="directions" ${!providerSettings.deepseek_configured||!project.master_approval?'disabled':''}>预估费用</button></div>`;if(kind==='prompt')return `<div class="panel"><h3>用自然语言修改字段</h3><textarea id="ai-prompt-instruction" class="search" placeholder="例如：只换场景，保持产品角度和光线" style="min-height:65px"></textarea><p><button class="smallbtn" data-ai="prompt" ${!providerSettings.deepseek_configured||!latest(project.prompts)?'disabled':''}>预估费用</button></p></div>`;return ''}
function chatAiButton(){return `<div class="panel"><h3>DeepSeek 创作辅助</h3><p class="muted tiny">输入会连同已确认简报发送；不会使用整个聊天记录。每次调用先预估费用并单独批准。</p><button class="smallbtn" data-ai="chat" ${!providerSettings.deepseek_configured||!approvedBrief()?'disabled':''}>对当前输入预估费用</button></div>`}
function aiModal(){const q=aiPending.quote;return `<div class="overlay"><div class="dialog"><div class="row between"><h2>批准 DeepSeek 调用</h2><button class="iconbtn" data-click="ai-cancel">×</button></div><p class="muted">模型 DeepSeek-V4.1-Flash（${esc(q.model)}） · 输入上界 ${q.input_token_bound} token · 输出上限 ${q.output_token_cap} token</p><div class="stat"><b>预计最多 ¥${Number(q.estimate).toFixed(2)}</b><span>基于本机填写的当前价格</span></div>${q.reason?`<div class="error">${esc(q.reason)}</div>`:'<div class="warning">模型返回内容需人工审核。调用后可能产生 API 费用。</div>'}<div class="row" style="margin-top:16px"><button class="ghost" data-click="ai-cancel">取消</button><button class="primary" data-click="ai-run" ${q.reason?'disabled':''}>批准本次调用</button></div></div></div>`}
async function requestAi(kind){try{let body={kind};if(kind==='facts'){body.source_id=$('#ai-source')?.value;if(!body.source_id)throw Error('请选择可读取的来源文件')}if(kind==='chat'){body.text=$('#chat-form textarea')?.value?.trim();if(!body.text)throw Error('请先输入问题')}if(kind==='prompt'){body.prompt_id=latest(project.prompts)?.id;body.text=$('#ai-prompt-instruction')?.value?.trim();if(!body.text)throw Error('请输入修改要求')}const quote=await api(`/projects/${project.id}/assist/quote`,body);aiPending={body,quote,request_id:crypto.randomUUID()};render()}catch(e){error(e)}}
async function runAi(){if(!aiPending)return;const pending=aiPending;const button=$('[data-click="ai-run"]');if(button){button.disabled=true;button.textContent='调用中…'}try{const response=await api(`/projects/${project.id}/assist/run`,{...pending.body,approved_quote:pending.quote.estimate,request_id:pending.request_id});project=response.project;if(['prompt','prompt_generate'].includes(pending.body.kind))currentPrompt=latest(project.prompts)?.id;aiPending=null;notify(response.result.result||'AI 辅助已完成，等待人工审核')}catch(e){aiPending=null;error(e)}}
function seeanyForm(kind){
  const names={master:'生成三视图候选',preview:'生成单张试图',plan:'SeeAny 策划套图',gallery:'生成已批准套图'};
  const images=project.sources.filter(s=>s.mime.startsWith('image/'));
  const options=images.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');
  const extra=kind==='master'?`${select('group','候选组',['1','2'])}${select('view_label','本地视角',['正面','侧面','背面','顶部','其他'])}${textField('views','SeeAny 视角预设','','官方示例：front；其余请按官方预设填写')}`:
    kind==='preview'?`<div class="field"><label>提示词版本</label><select name="prompt_id">${project.prompts.map((p,i)=>`<option value="${p.id}" ${i===project.prompts.length-1?'selected':''}>v${i+1} · ${esc(p.fields.purpose||p.id)}</option>`).join('')}</select></div>`:
    kind==='plan'?area('requirement','策划补充要求','','例如：优先白底主图和材质细节图'):
    `<div class="field"><label>已批准方案</label><select name="gallery_id">${project.gallery.filter(g=>g.approved).map(g=>`<option value="${g.id}">${fmt(g.created)} · ${g.items.length} 张</option>`).join('')}</select></div>`;
  const fee=kind==='plan'?'<p class="muted tiny">接口文档当前标价 ¥0.10/次，提交前仍需批准。</p>':textField('estimate','本次预计费用（元）','','请先按 SeeAny 当前价格核对；未知则不能提交');
  return `<div class="panel"><h3>SeeAny · ${names[kind]}</h3><p class="muted tiny">参考图会先上传到 SeeAny；生成结果需回到任务页同步并人工审核。图片上传 URL 可能在 14 天后失效。</p><form class="seeany-form" data-kind="${kind}"><div class="grid2"><div><div class="field"><label>商品参考图（Ctrl 可多选，1～6 张）</label><select name="source_ids" multiple size="${Math.min(Math.max(images.length,2),6)}" required>${options}</select></div>${extra}</div><div>${fee}<div class="warning">仅使用已确认简报和本次选择的图片。正式调用可能扣费；远端状态不明时不要重复提交。</div><button class="primary" ${!images.length?'disabled':''}>核对请求与费用</button></div></div></form></div>`;
}
function seeanyTasks(){const items=project.tasks.filter(t=>t.provider==='SeeAny');return `<div class="panel"><h3>SeeAny 远端任务</h3>${items.map(t=>{const cost=project.costs.find(c=>c.task_id===t.id&&c.status==='确认');return `<div class="item"><div class="item-main"><h4>${esc(t.description)} ${badge(t.status,t.status==='失败'?'red':'orange')}</h4><p>${esc(t.reason)} · 预计 ¥${Number(t.estimate||0).toFixed(2)} · ${cost?'实际 ¥'+Number(cost.amount).toFixed(2):'实际费用待核对'} · 已导入 ${t.imported_urls?.length||0} 张</p><p class="mono">${esc(t.remote_id||'尚无远端标识')}</p></div><div>${t.remote_id?`<button class="smallbtn" data-seeany-status="${t.id}">同步状态 / 导入结果</button>`:''}${!cost&&['待审核','完成','部分失败','失败'].includes(t.status)?`<button class="smallbtn" data-seeany-cost="${t.id}">记录实际费用</button>`:''}</div></div>`}).join('')||empty('暂无 SeeAny 任务','在三视图、提示词或套图页核对并提交。')}</div>`}
function seeanyModal(){const q=seeanyPending.quote;return `<div class="overlay"><div class="dialog"><div class="row between"><h2>批准 SeeAny · ${esc(q.label)}</h2><button class="iconbtn" data-seeany-cancel>×</button></div><p class="muted">参考图：${q.source_names.map(esc).join('、')}</p><p class="muted">阶段 ${esc(q.stage)} · 模型 ${esc(q.summary.model)} · 分辨率 ${esc(q.summary.size)} · 预计输出 ${q.summary.count} 张 ${q.summary.views?'· 视角预设 '+esc(q.summary.views):''}</p><details><summary>查看本次完整请求参数</summary><pre style="white-space:pre-wrap;max-height:250px;overflow:auto">${esc(JSON.stringify(q.request_preview,null,2))}</pre></details><div class="stat"><b>${q.estimate==null?'费用未知':'预计 ¥'+Number(q.estimate).toFixed(2)}</b><span>${q.kind==='plan'?'当前官方文档价格':'你按供应商价格填写的预计费用；实际扣费须核对'}</span></div>${q.reason?`<div class="error">${esc(q.reason)}</div>`:'<div class="warning">确认后将上传所选图片并提交给 SeeAny，可能产生 API 费用。结果需人工核对产品真实性。</div>'}<div class="row" style="margin-top:16px"><button class="ghost" data-seeany-cancel>取消</button><button class="primary" data-seeany-run ${q.reason?'disabled':''}>确认并提交</button></div></div></div>`}
function bindSeeany(){
  $$('.seeany-form').forEach(form=>form.onsubmit=async e=>{e.preventDefault();try{const data=new FormData(form);const body=Object.fromEntries(data.entries());body.kind=form.dataset.kind;body.source_ids=data.getAll('source_ids');const quote=await api(`/projects/${project.id}/seeany/quote`,body);seeanyPending={body,quote,request_id:crypto.randomUUID()};render()}catch(err){error(err)}});
  $$('[data-seeany-cancel]').forEach(el=>el.onclick=()=>{seeanyPending=null;render()});
  const run=$('[data-seeany-run]');if(run)run.onclick=async()=>{const pending=seeanyPending;run.disabled=true;run.textContent='提交中…';try{const r=await api(`/projects/${project.id}/seeany/run`,{...pending.body,approved_fingerprint:pending.quote.fingerprint,request_id:pending.request_id});project=r.project;seeanyPending=null;notify(r.result.status==='待审核'?'策划方案已生成，请审核':'SeeAny 任务已提交，到任务页同步结果')}catch(err){seeanyPending=null;try{project=await api(`/projects/${project.id}`)}catch{}error(err)}};
  $$('[data-seeany-status]').forEach(el=>el.onclick=async()=>{el.disabled=true;el.textContent='同步中…';try{const r=await api(`/projects/${project.id}/seeany/status`,{task_id:el.dataset.seeanyStatus});project=r.project;notify(`SeeAny ${r.result.remote_status||'处理中'}；已导入 ${r.result.imported} 张候选图`)}catch(err){error(err)}});
  $$('[data-seeany-cost]').forEach(el=>el.onclick=async()=>{const amount=prompt('请对照 SeeAny 开发者账户记录填写实际扣费（元）；确认退款可填 0：','');if(amount===null||amount==='')return;try{await act('cost',{task_id:el.dataset.seeanyCost,amount});notify('实际费用已记录')}catch(err){error(err)}});
}
init();
